const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

const general_button = require('general_button')
const send_btc = require('send_btc')
const receive_btc = require('receive_btc')

module.exports = action_buttons

async function action_buttons(opts = {}, protocol) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = { style: inject, data: ondata }
  const _ = { send_general: null, receive_general: null }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  shadow.innerHTML = `
    <div class="action-buttons-container">
      <div class="send-receive-buttons">
        <div id="send-button-container"></div>
        <div id="receive-button-container"></div>
      </div>
      <div class="overlay send-overlay hidden"></div>
      <div class="overlay receive-overlay hidden"></div>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')
  const send_container = shadow.querySelector('#send-button-container')
  const receive_container = shadow.querySelector('#receive-button-container')
  const send_overlay = shadow.querySelector('.send-overlay')
  const receive_overlay = shadow.querySelector('.receive-overlay')

  const subs = await sdb.watch(onbatch)

  // sendUp sends a message up to home_contents; it also returns a function
  let _sendToParent = null
  let send_el = null
  let receive_el = null

  let currentBtcBalance = 0
  let _lastBtcTxs = []  // cache for populating templates when send panel opens late

  const sendUp = protocol
    ? protocol(function receiveFromParent(msg) {
      if (msg.type === 'btc_balance_updated') {
        currentBtcBalance = msg.data?.balance || 0
        if (send_el && typeof send_el.updateBalance === 'function') {
          send_el.updateBalance(currentBtcBalance)
        }
      }
      // Real BTC transaction history for populating send templates
      if (msg.type === 'btc_transactions_updated') {
        const txs = msg.data?.txs || []
        _lastBtcTxs = txs  // cache for when send panel is opened later
        if (send_el && typeof send_el.updateTemplates === 'function') {
          send_el.updateTemplates(txs)
        }
      }
      // home_contents sends back btc_address_generated here
      if (msg.type === 'btc_address_generated') {
        const addr = msg.data?.address || ''
        if (receive_el) {
          receive_el.setAddress(addr)
        }
      }
      if (msg.type === 'btc_description_updated') {
        const success = msg.data?.success !== false
        if (receive_el && typeof receive_el.onDescriptionUpdated === 'function') {
          receive_el.onDescriptionUpdated(success)
        }
      }
      if (msg.type === 'btc_payment_sent') {
        if (send_el && typeof send_el.onPaymentSent === 'function') {
          send_el.onPaymentSent(msg.data)
        }
      }
    })
    : null

  // send a message up to home_contents
  function sendToHome(type, data) {
    if (typeof sendUp === 'function') {
      sendUp({ from: 'action_buttons', type, data })
    }
  }

  // -------------------- Buttons --------------------
  const send_button = await general_button(subs[0], button_protocol('send_general'))
  const receive_button = await general_button(subs[1], button_protocol('receive_general'))

  send_container.appendChild(send_button)
  receive_container.appendChild(receive_button)

  send_button._action = 'send_message'
  receive_button._action = 'receive_message'


  // -------------------- Overlay helpers --------------------
  function close_all_overlays(except) {
    if (except !== 'send') send_overlay.classList.add('hidden')
    if (except !== 'receive') receive_overlay.classList.add('hidden')
  }

  function handle_outside_click(event) {
    const target = event.target
    const clicked_inside =
      send_overlay.contains(target) || receive_overlay.contains(target)
    const clicked_button =
      send_button.contains(target) || receive_button.contains(target)

    if (!clicked_inside && !clicked_button) close_all_overlays(null)
  }

  shadow.addEventListener('click', handle_outside_click)

  // -------------------- Button Clicks --------------------
  send_button.onclick = async (e) => {
    e.stopPropagation()
    try {
      if (send_button._action !== 'send_message') {
        console.warn('Send button action check failed. _action is: ' + send_button._action)
        return
      }
      close_all_overlays('send')

      if (!send_el) {
        send_el = await send_btc(subs[2], {
          onClose: () => send_overlay.classList.add('hidden'),
          onSend: function (address, amount) {
            sendToHome('send_btc_payment', { address, amount })
          }
        })
        send_overlay.appendChild(send_el)
      }

      // Always push latest balance when the panel opens
      if (typeof send_el.updateBalance === 'function') {
        send_el.updateBalance(currentBtcBalance)
      }
      // Push latest tx history for templates when panel opens
      if (typeof send_el.updateTemplates === 'function' && _lastBtcTxs.length > 0) {
        send_el.updateTemplates(_lastBtcTxs)
      }

      send_overlay.classList.remove('hidden')
      sendToHome('send', null)
    } catch (err) {
      console.error('Error in click handler:', err)
    }
  }

  receive_button.onclick = async (e) => {
    e.stopPropagation()
    if (receive_button._action !== 'receive_message') return
    close_all_overlays('receive')

    if (!receive_el) {
      // Create once — subs[3] is a single-use channel, cannot be recreated
      receive_el = await receive_btc(subs[3], {
        onClose: () => receive_overlay.classList.add('hidden'),
        // Called on first mount AND by reset() on every subsequent open
        onGenerate: function (description) {
          sendToHome('generate_btc_address', { description })
        },
        // Called when user clicks "Add Description" — updates description on existing address
        onUpdateDescription: function (address, description) {
          sendToHome('update_btc_description', { address, description })
        }
      })
      receive_overlay.appendChild(receive_el)
    } else {
      // Component already exists — reset it to get a fresh address
      receive_el.reset()
    }

    receive_overlay.classList.remove('hidden')
    sendToHome('receive', null)
  }

  // -------------------- Initial Config --------------------
  _.send_general?.({ type: 'button_name', data: { name: 'Send', action: 'send_message' } })
  _.receive_general?.({ type: 'button_name', data: { name: 'Receive', action: 'receive_message' } })

  return el

  // -------------------- Helpers --------------------
  function fail(data, type) { throw new Error('Invalid message type', { cause: { data, type } }) }
  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(p => drive.get(p).then(f => f.raw)))
      const handler = on[type] || fail
      handler(data, type)
    }
  }
  function inject(data) { style.textContent = data[0] }
  async function ondata(data) { const buttonData = data[0]?.value || {} }
  function button_protocol(key) { return send => { _[key] = send; return send } }
}

// -------------------- Fallback for STATE --------------------
function fallback_module() {

  return {
    api,
    _: { 'general_button': { $: '' }, 'send_btc': { $: '' }, 'receive_btc': { $: '' } }
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    const general_button = { mapping: { style: 'style', data: 'data' }, 0: {}, 1: {} }
    const send_btc = { mapping: { style: 'style', data: 'data', icons: 'icons' }, 2: '' }
    const receive_btc = { mapping: { style: 'style', data: 'data', icons: 'icons' }, 3: '' }

    return {
      drive: {
        'style/': { 'action_buttons.css': { '$ref': 'action_buttons.css' } },
        'data/': { 'opts.json': { raw: opts || {} } }
      },
      _: { general_button, send_btc, receive_btc }
    }
  }
}